      "ar": "وَعَدَ اللَّهُ الَّذِينَ ءَامَنُواْ وَعَمِلُواْ الصَّـٰلِحَٰتِ لَهُم مَّغْفِرَةٌ وَأَجْرٌ عَظِيمٌ",
      "translit": "Waʿada llāhu lladhīna āmanū waʿamilū ṣ-ṣāliḥāti lahum maghfiratun waʾajrun ʿaẓīm",
