        "tr": {
          "auteur": "Diyanet İşleri Başkanlığı",
          "texte": "Ettiği zulümden sonra tevbe edip düzelen kimse, bilsin ki Allah onun tevbesini kabul eder. Allah şüphesiz Bağışlayan'dır, merhametli olandır"
        }
